import json, struct

with open('/app/trunc.db','rb') as f:
    data = f.read()

cell_count = int.from_bytes(data[3:5], 'big')

def read_varint(b, off):
    result = 0
    for i in range(9):
        x = b[off+i]
        if i == 8:
            result = (result << 8) | x
            return result, off+9
        result = (result << 7) | (x & 0x7f)
        if not (x & 0x80):
            return result, off+i+1
    return result, off+9

ptrs = [int.from_bytes(data[8+i*2:10+i*2],'big') for i in range(cell_count)]
rows = []
for p in ptrs:
    off = p
    plen, off = read_varint(data, off)
    rowid, off = read_varint(data, off)
    payload = data[off:off+plen]
    hlen, h = read_varint(payload, 0)
    types = []
    pos = h
    while pos < hlen:
        t, pos = read_varint(payload, pos)
        types.append(t)
    vals = []
    pos = hlen
    for t in types:
        if t == 0:
            vals.append(None)
        elif t == 1:
            vals.append(int.from_bytes(payload[pos:pos+1],'big',signed=True)); pos+=1
        elif t == 2:
            vals.append(int.from_bytes(payload[pos:pos+2],'big',signed=True)); pos+=2
        elif t == 3:
            vals.append(int.from_bytes(payload[pos:pos+3],'big',signed=True)); pos+=3
        elif t == 4:
            vals.append(int.from_bytes(payload[pos:pos+4],'big',signed=True)); pos+=4
        elif t == 5:
            vals.append(int.from_bytes(payload[pos:pos+6],'big',signed=True)); pos+=6
        elif t == 6:
            vals.append(int.from_bytes(payload[pos:pos+8],'big',signed=True)); pos+=8
        elif t == 7:
            vals.append(struct.unpack('>d', payload[pos:pos+8])[0]); pos+=8
        elif t == 8:
            vals.append(0)
        elif t == 9:
            vals.append(1)
        elif t >= 12 and t % 2 == 0:
            n = (t-12)//2; vals.append(payload[pos:pos+n]); pos+=n
        elif t >= 13 and t % 2 == 1:
            n = (t-13)//2; vals.append(payload[pos:pos+n].decode('utf-8','replace')); pos+=n
        else:
            vals.append(None)
    rows.append((rowid, vals))

rows.sort(key=lambda r: r[0])
out = [{"word": v[1], "value": v[2]} for _, v in rows if v[1] is not None]
with open('/app/recover.json','w') as f:
    json.dump(out, f, indent=2)
print(json.dumps(out, indent=2))
print('rows recovered:', len(out))
EOF
